-- Phase 68: operational landlord statements, not a trust-accounting ledger.
create table public.rental_landlord_statements(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),property_id uuid not null references public.rental_properties(id),period_start date not null,period_end date not null check(period_end>=period_start),version integer not null,summary jsonb not null default '{}'::jsonb,document_link text,status text not null default 'generated' check(status in('generated','archived')),generated_by uuid not null references auth.users(id),generated_at timestamptz not null default now(),unique(property_id,period_start,period_end,version));
create index rental_landlord_statements_property_period_idx on public.rental_landlord_statements(property_id,period_end desc);create index rental_landlord_statements_org_generated_idx on public.rental_landlord_statements(organisation_id,generated_at desc);create index rental_landlord_statements_generated_by_idx on public.rental_landlord_statements(generated_by);
alter table public.rental_landlord_statements enable row level security;create policy "rental_landlord_statements_manager_read" on public.rental_landlord_statements for select to authenticated using(public.rental_financial_manager_authorized(organisation_id));
create or replace function public.rental_generate_landlord_statement(p_property uuid,p_start date,p_end date,p_document_link text default null)returns jsonb language plpgsql security definer set search_path='' as $$ declare v_org uuid;v_version int;v_id uuid;begin select organisation_id into v_org from public.rental_properties where id=p_property;if auth.uid() is null or not found or not public.rental_financial_manager_authorized(v_org) or p_start is null or p_end is null or p_end<p_start then raise exception 'Invalid statement request';end if;select coalesce(max(version),0)+1 into v_version from public.rental_landlord_statements where property_id=p_property and period_start=p_start and period_end=p_end;insert into public.rental_landlord_statements(organisation_id,property_id,period_start,period_end,version,summary,document_link,generated_by)values(v_org,p_property,p_start,p_end,v_version,jsonb_build_object('notice','Operational rental statement only; it is not a trust-accounting statement.','open_maintenance',(select count(*)from public.rental_maintenance_requests where property_id=p_property and status not in('resolved','cancelled'))),nullif(btrim(coalesce(p_document_link,'')),''),auth.uid())returning id into v_id;return jsonb_build_object('statement_id',v_id,'version',v_version);end $$;
create or replace function public.rental_get_landlord_statements(p_org uuid)returns jsonb language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.rental_financial_manager_authorized(p_org)then raise exception 'Not authorized';end if;return coalesce((select jsonb_agg(to_jsonb(x)order by x.generated_at desc)from(select * from public.rental_landlord_statements where organisation_id=p_org order by generated_at desc limit 100)x),'[]'::jsonb);end $$;
revoke all on function public.rental_generate_landlord_statement(uuid,date,date,text)from public,anon;revoke all on function public.rental_get_landlord_statements(uuid)from public,anon;grant execute on function public.rental_generate_landlord_statement(uuid,date,date,text)to authenticated;grant execute on function public.rental_get_landlord_statements(uuid)to authenticated;
